#!/usr/bin/env python3
from __future__ import annotations
import argparse, datetime as dt, json, os, re, subprocess, sys
from dataclasses import dataclass, asdict
from pathlib import Path

PACKAGE='PRISMA_LICENSE_SIGNATURE_DISPATCH_FIX_10B'
VERSION='1.0.0'
BLOCK_BEGIN='rem PRISMA_LICENSE_SIGNATURE_10B_DISPATCH_FIX_START'
BLOCK_END='rem PRISMA_LICENSE_SIGNATURE_10B_DISPATCH_FIX_END'
COMMANDS=(
 ('license-signature-policy','policy'),('license-signature-registry','registry'),('license-signature-audit','audit'),
 ('license-signature-verify-fixture','verify-fixture'),('license-signature-env-smoke','env-smoke'),
 ('license-signature-smoke','smoke'),('license-signature-contract','contract'))
@dataclass
class Finding:
    code:str; severity:str; message:str; line:int|None=None
@dataclass
class Analysis:
    terminal_path:str; unknown_line:int|None; block_line:int|None; commands_before_unknown:dict[str,bool]; findings:list[Finding]
    @property
    def ok(self): return not any(f.severity=='error' for f in self.findings)
def stamp(): return dt.datetime.now().strftime('%y%m%d_%H%M')
def root_arg(v): return Path(v).expanduser().resolve() if v else Path(__file__).resolve().parents[3]
def downloads(root):
    p=Path('F:/descargasf')
    try: p.mkdir(parents=True, exist_ok=True); return p
    except Exception:
        p=root/'local-runtime'/'reports'; p.mkdir(parents=True, exist_ok=True); return p
def terminal(root): return root/'terminal_de_venta.cmd'
def signature(root): return root/'tooling'/'licensing'/'signature10'/'license_signature_10.py'
def line_of(text, idx): return text.count('\n',0,idx)+1
def first_unknown(text): return re.search(r'(?im)^\s*goto\s+unknown\s*$', text)
def cmd_line(text, command):
    m=re.search(r'(?im)^\s*if\s+/I\s+"%~1"\s*==\s*"'+re.escape(command)+r'"', text)
    return line_of(text,m.start()) if m else None
def dispatch_block():
    out=[BLOCK_BEGIN,'rem Must be before goto unknown. Installed by 10B.']
    for c,s in COMMANDS:
        out += [f'if /I "%~1"=="{c}" (', f'  python "%TV_SYSTEM_ROOT%\\tooling\\licensing\\signature10\\license_signature_10.py" {s} --root "%TV_SYSTEM_ROOT%"', '  exit /b %ERRORLEVEL%', ')']
    out.append(BLOCK_END); return '\r\n'.join(out)
def strip_block(text): return re.sub(re.escape(BLOCK_BEGIN)+r'.*?'+re.escape(BLOCK_END),'',text,flags=re.I|re.S)
def patch_text(text):
    text=strip_block(text); m=first_unknown(text)
    if not m: raise RuntimeError('No encontre goto unknown')
    return text[:m.start()].rstrip()+'\r\n'+dispatch_block()+'\r\n'+text[m.start():].lstrip()
def analyze(root):
    p=terminal(root); findings=[]; state={}
    if not p.exists(): return Analysis(str(p),None,None,{},[Finding('terminal_missing','error',f'No existe {p}')])
    text=p.read_text(encoding='utf-8', errors='ignore')
    um=first_unknown(text); uline=line_of(text,um.start()) if um else None
    bm=re.search(re.escape(BLOCK_BEGIN), text, re.I); bline=line_of(text,bm.start()) if bm else None
    if not um: findings.append(Finding('unknown_missing','error','No hay goto unknown'))
    if not bm: findings.append(Finding('fix_block_missing','error','Falta bloque 10B'))
    elif uline and bline and bline>uline: findings.append(Finding('fix_block_unreachable','error','Bloque 10B esta despues de goto unknown',bline))
    for c,_s in COMMANDS:
        cl=cmd_line(text,c); ok=cl is not None and (uline is None or cl<uline); state[c]=ok
        if cl is None: findings.append(Finding('command_missing','error',f'Falta {c}'))
        elif uline and cl>uline: findings.append(Finding('command_unreachable','error',f'{c} esta despues de goto unknown',cl))
    if not signature(root).exists(): findings.append(Finding('signature10_missing','error',f'Falta {signature(root)}'))
    return Analysis(str(p),uline,bline,state,findings)
def report(root,name,lines):
    path=downloads(root)/f'terminal_venta_signature_dispatch_10b_{name}_{stamp()}.md'; path.write_text('\n'.join(lines)+'\n',encoding='utf-8'); return path
def render(a):
    lines=[f'# {PACKAGE} Analysis','',f'Terminal: `{a.terminal_path}`',f'Unknown line: `{a.unknown_line}`',f'Block line: `{a.block_line}`','','## Commands']
    for k,v in a.commands_before_unknown.items(): lines.append(f'- `{k}`: '+('OK' if v else 'BLOCKED'))
    lines += ['','## Findings']
    if not a.findings: lines.append('- OK')
    for f in a.findings: lines.append(f'- {f.severity.upper()} `{f.code}` line={f.line}: {f.message}')
    lines.append(''); lines.append('FINAL READY' if a.ok else 'BLOCKED'); return lines
def command_analyze(args):
    root=root_arg(args.root); a=analyze(root); lines=render(a); path=report(root,'analysis',lines)
    print('\n'.join(lines)); print(f'REPORT {path}'); return 0 if a.ok else 2
def command_patch(args):
    root=root_arg(args.root); p=terminal(root); before=p.read_text(encoding='utf-8', errors='ignore'); after=patch_text(before)
    if args.dry_run: print('DRY RUN would patch terminal before goto unknown'); return 0
    b=root/'.prisma_license_signature_dispatch_10b_backups'/stamp(); b.mkdir(parents=True,exist_ok=True); (b/'terminal_de_venta.cmd').write_text(before,encoding='utf-8',newline='')
    p.write_text(after,encoding='utf-8',newline=''); print(f'BACKUP {b}'); return command_analyze(args)
def command_smoke(args):
    root=root_arg(args.root); a=analyze(root); lines=render(a); rc=0 if a.ok else 2
    script=signature(root)
    if rc==0:
        proc=subprocess.run([sys.executable,str(script),'smoke','--root',str(root)],text=True,capture_output=True,timeout=180)
        lines += ['','## Direct signature10 smoke',f'Exit: `{proc.returncode}`','```text',(proc.stdout+proc.stderr).strip()[:8000],'```']
        if proc.returncode or 'FINAL READY' not in proc.stdout: rc=2
    if os.name=='nt' and rc==0:
        proc=subprocess.run(['cmd.exe','/c',str(terminal(root)),'license-signature-smoke'],text=True,capture_output=True,timeout=180)
        out=(proc.stdout+proc.stderr)
        lines += ['','## terminal_de_venta.cmd smoke',f'Exit: `{proc.returncode}`','```text',out.strip()[:8000],'```']
        if proc.returncode or 'Unknown command' in out or 'FINAL READY' not in out: rc=2
    lines.append(''); lines.append('FINAL READY' if rc==0 else 'BLOCKED'); path=report(root,'smoke',lines); print(f'REPORT {path}'); print('FINAL READY' if rc==0 else 'BLOCKED'); return rc
def command_registry(args):
    root=root_arg(args.root); print((root/'tooling'/'licensing'/'dispatch10b'/'terminal_command_registry.json').read_text(encoding='utf-8')); return 0
def main(argv=None):
    p=argparse.ArgumentParser(); p.add_argument('command',choices=['analyze','patch','smoke','registry']); p.add_argument('--root'); p.add_argument('--dry-run',action='store_true')
    a=p.parse_args(argv)
    return {'analyze':command_analyze,'patch':command_patch,'smoke':command_smoke,'registry':command_registry}[a.command](a)
if __name__=='__main__': raise SystemExit(main())

